function render(){gl.disable(gl.DEPTH_TEST);gl.useProgram(skyProg);gl.bindBuffer(gl.ARRAY_BUFFER,skyBuf);const a=gl.getAttribLocation(skyProg,'a');gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,2,gl.FLOAT,false,0,0);gl.uniform1f(gl.getUniformLocation(skyProg,'yaw'),player.yaw);gl.uniform1f(gl.getUniformLocation(skyProg,'aspect'),canvas.width/canvas.height);gl.drawArrays(gl.TRIANGLES,0,3);gl.enable(gl.DEPTH_TEST);gl.clear(gl.DEPTH_BUFFER_BIT);gl.useProgram(prog);gl.uniformMatrix4fv(loc.uVP,false,vp());gl.uniform3f(loc.uEye,player.x,player.y,player.z);gl.uniform1f(loc.uTime,reduced?0:time);draw(distant);draw(sea,[0,0,0],0,1);draw(terrain);draw(foam);draw(world);draw(clouds);for(const npc of npcs){const target=Math.atan2(player.x-npc.x,player.z-npc.z);let diff=Math.atan2(Math.sin(target-npc.angle),Math.cos(target-npc.angle));npc.angle+=diff*.018;draw(npc.mesh,[npc.x,npc.y+(reduced?0:Math.sin(time*.75+npc.x)*.013),npc.z],npc.angle);}}
function occupied(x,z){if(!walkable(x,z))return true;return obstacles.some(([a,b,r])=>Math.hypot(x-a,z-b)<r+.23);}
function update(dt){let forward=0,strafe=0,turn=0;if(held){const i=pointerInput(pointer.x,pointer.y);forward=i.forward;strafe=i.strafe;turn=i.turn;}forward+=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0);strafe+=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0);turn+=(keys.has('ArrowRight')||keys.has('KeyE')?1:0)-(keys.has('ArrowLeft')||keys.has('KeyQ')?1:0);player.yaw-=clamp(turn,-1,1)*dt*.95;const len=Math.max(1,Math.hypot(forward,strafe));forward/=len;strafe/=len;const speed=keys.has('ShiftLeft')||keys.has('ShiftRight')?4.4:2.65,c=Math.cos(player.yaw),s=Math.sin(player.yaw),vx=(strafe*c-forward*s)*speed,vz=(-forward*c-strafe*s)*speed;const t=1-Math.exp(-dt*9);player.vx+=(vx-player.vx)*t;player.vz+=(vz-player.vz)*t;const nx=player.x+player.vx*dt,nz=player.z+player.vz*dt;if(!occupied(nx,player.z))player.x=nx;if(!occupied(player.x,nz))player.z=nz;const floor=height(player.x,player.z)+1.65;player.y+=(floor-player.y)*(1-Math.exp(-dt*10));
 for(const npc of npcs){const dist=Math.hypot(player.x-npc.x,player.z-npc.z);if(dist<3.5&&time-npc.last>23&&time>greetUntil+1){npc.last=time;document.querySelector('#speaker').textContent=npc.name;document.querySelector('#words').textContent=npc.lines[npc.index%npc.lines.length];npc.index++;document.querySelector('#greeting').style.opacity=1;greetUntil=time+7;chime();break;}}
 if(time>greetUntil)document.querySelector('#greeting').style.opacity=0;
 const places=[['浜の入口','THE LANDING',8,27,7],['オリーブの小径','OLIVE PATH',0,8,6],['潮見の鳥居','THE TIDE GATE',23,8,6],['名のない祠','THE HILL SHRINE',-4,-13,6],['潮待ちの砂州','THE TIDAL PATH',-31,22,8],['夢のつづき','THE OTHER SHORE',-48,22,5]];
 for(const [name,en,x,z,r] of places)if(!shownPlaces.has(name)&&Math.hypot(player.x-x,player.z-z)<r&&time>placeUntil+1){shownPlaces.add(name);document.querySelector('#place-jp').textContent=name;document.querySelector('#place-en').textContent=en;document.querySelector('#place').style.opacity=1;placeUntil=time+5;break;}
 if(time>placeUntil)document.querySelector('#place').style.opacity=0;
}
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;time+=dt;if(started){let remaining=dt;while(remaining>0){const step=Math.min(.025,remaining);update(step);remaining-=step;}}render();requestAnimationFrame(frame);}requestAnimationFrame(frame);
function setPointer(e){const r=canvas.getBoundingClientRect();pointer.x=clamp((e.clientX-r.left)/r.width*2-1,-1,1);pointer.y=clamp((e.clientY-r.top)/r.height*2-1,-1,1);pointer.x=Math.abs(pointer.x)<.08?0:pointer.x;pointer.y=Math.abs(pointer.y)<.08?0:pointer.y;}
canvas.addEventListener('pointerdown',e=>{if(!started||e.button>0||pointerId!==null)return;held=true;pointerId=e.pointerId;setPointer(e);canvas.setPointerCapture(e.pointerId);canvas.focus();});canvas.addEventListener('pointermove',e=>{if(e.pointerId===pointerId)setPointer(e);});function release(e){if(!e||e.pointerId===pointerId){held=false;pointerId=null;}}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.addEventListener('lostpointercapture',release);canvas.addEventListener('contextmenu',e=>e.preventDefault());
const gameKeys=['KeyW','KeyA','KeyS','KeyD','KeyQ','KeyE','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','ShiftLeft','ShiftRight'];addEventListener('keydown',e=>{if(!started&&e.code==='Enter'){begin();return;}if(started&&gameKeys.includes(e.code)){e.preventDefault();keys.add(e.code);}if(e.code==='Escape')resetInput();});addEventListener('keyup',e=>keys.delete(e.code));function resetInput(){keys.clear();release();player.vx=player.vz=0;}addEventListener('blur',resetInput);document.addEventListener('visibilitychange',()=>{if(document.hidden){resetInput();if(audioCtx)audioCtx.suspend();}else if(audioCtx&&started)audioCtx.resume().catch(()=>{});});
let audioCtx,master;function audio(){try{audioCtx=new(window.AudioContext||window.webkitAudioContext)();master=audioCtx.createGain();master.gain.value=.18;master.connect(audioCtx.destination);const buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*4,audioCtx.sampleRate),v=buffer.getChannelData(0);let b=0;for(let i=0;i<v.length;i++){b=(b+(Math.random()*2-1)*.018)/1.018;v[i]=b*3;}const noise=audioCtx.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=650;const gain=audioCtx.createGain();gain.gain.value=.4;noise.connect(filter);filter.connect(gain);gain.connect(master);noise.start();const lfo=audioCtx.createOscillator(),lg=audioCtx.createGain();lfo.frequency.value=.09;lg.gain.value=.15;lfo.connect(lg);lg.connect(gain.gain);lfo.start();audioCtx.resume().catch(()=>{});}catch{}}
function chime(){if(!audioCtx||audioCtx.state!=='running')return;for(const [i,f] of [523.25,783.99].entries()){const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime+i*.15;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.035,t+.03);g.gain.exponentialRampToValueAtTime(.0001,t+2);o.connect(g);g.connect(master);o.start(t);o.stop(t+2);}}
function begin(){if(started)return;started=true;greetUntil=time+2;placeUntil=time-2;document.body.classList.add('playing');canvas.focus();audio();document.querySelector('#hint').style.opacity=1;setTimeout(()=>document.querySelector('#hint').style.opacity=0,4500);}
document.querySelector('#begin').addEventListener('click',begin);
